fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants we actually consider
    let limit = usize::min(n as usize, participations.len());

    // Count those who can attend at least k more sessions
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attended| 5 - attended >= k)
        .count();

    // We can form teams of 3
    (eligible_count / 3) as u8
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn example_cases() {
        // Example 1: participations = [2, 3, 5, 0, 1], k = 2, n = 5
        // Eligible: 2->3 remaining, 3->2, 5->0, 0->5, 1->4 => those with rem >= 2 are indices 0,1,3,4 => 4 people => 1 team
        assert_eq!(solve(5, 2, vec![2, 3, 5, 0, 1]), 1);

        // Example 2: fewer than n elements
        assert_eq!(solve(10, 1, vec![5, 4, 3]), 0); // only 3 people, none can attend ≥1 more

        // Example 3: exactly enough for one team
        assert_eq!(solve(3, 0, vec![5, 5, 5]), 1);

        // Example 4: more participants but limit to n
        assert_eq!(solve(2, 5, vec![0, 0, 0, 0]), 0); // only first 2, each has 5 remaining => 2 eligibles => 0 teams
    }
}